document.getElementById('burst').onclick=function(){splatStack.push(12)};document.getElementById('pause').onclick=function(){config.PAUSED=!config.PAUSED;this.textContent=config.PAUSED?'继续':'暂停'};document.getElementById('quality').onclick=function(){config.DYE_RESOLUTION=config.DYE_RESOLUTION===512?256:512;initFramebuffers();this.textContent=config.DYE_RESOLUTION===512?'精细':'流畅'};document.getElementById('clear').onclick=function(){gl.clearColor(0,0,0,1);gl.bindFramebuffer(gl.FRAMEBUFFER,dye.read.fbo);gl.clear(gl.COLOR_BUFFER_BIT);gl.bindFramebuffer(gl.FRAMEBUFFER,dye.write.fbo);gl.clear(gl.COLOR_BUFFER_BIT)};